import type { Plugin } from "@opencode-ai/plugin"
import { tool } from "@opencode-ai/plugin"
import {
  existsSync, mkdirSync, readFileSync, writeFileSync,
  unlinkSync, statSync, openSync, readSync, closeSync, appendFileSync,
} from "fs"
import { homedir } from "os"
import { join } from "path"

const BG_DIR = join(homedir(), "opencode", "bg")
const JOBS_FILE = join(BG_DIR, "jobs.json")
const MAX_CONCURRENT = 20
const MAX_LOG_SIZE = 50 * 1024 * 1024
const MAX_HISTORY = 100
const JOB_ID_LENGTH = 6

interface JobInfo {
  id: string
  command: string
  shell: string
  status: "running" | "completed" | "failed" | "killed" | "timeout"
  process?: any
  outputFile: string
  startTime: number
  endTime?: number
  exitCode?: number
}

const jobs = new Map<string, JobInfo>()

function ensureDir(dir: string) {
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true })
}

function genJobId(): string {
  const chars = "0123456789abcdef"
  let id = "bg_"
  for (let i = 0; i < JOB_ID_LENGTH; i++) id += chars[Math.floor(Math.random() * 16)]
  return id
}

const IS_WINDOWS = process.platform === "win32"

type ShellName = "pwsh" | "powershell" | "cmd" | "bash" | "sh" | "zsh"

interface ShellConfig {
  exe: string
  args: string[]
  encodingCommand?: (cmd: string) => string
}

const SHELL_CONFIGS: Record<ShellName, ShellConfig> = {
  pwsh: {
    exe: "pwsh",
    args: ["-NoProfile", "-Command"],
    encodingCommand: (cmd) =>
      `[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; ${cmd}`,
  },
  powershell: {
    exe: "powershell",
    args: ["-NoProfile", "-Command"],
    encodingCommand: (cmd) =>
      `[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; ${cmd}`,
  },
  cmd: {
    exe: "cmd",
    args: ["/c"],
    encodingCommand: (cmd) => `chcp 65001 > nul && ${cmd}`,
  },
  bash: { exe: "bash", args: ["-c"] },
  sh: { exe: "sh", args: ["-c"] },
  zsh: { exe: "zsh", args: ["-c"] },
}

const WINDOWS_FALLBACK: ShellName[] = ["pwsh", "powershell", "cmd"]
const UNIX_FALLBACK: ShellName[] = ["bash", "sh"]

function isShellAvailable(shell: ShellName): boolean {
  try {
    const result = Bun.spawnSync({
      cmd: IS_WINDOWS ? ["where", SHELL_CONFIGS[shell].exe] : ["which", SHELL_CONFIGS[shell].exe],
      stdout: "pipe",
      stderr: "pipe",
    })
    return result.exitCode === 0
  } catch {
    return false
  }
}

function resolveShell(requested?: string): ShellName {
  if (requested) {
    const s = requested.toLowerCase() as ShellName
    if (!SHELL_CONFIGS[s]) throw new Error(`Unknown shell '${requested}'. Supported: pwsh, powershell, cmd, bash, sh, zsh`)
    if (!isShellAvailable(s)) throw new Error(`Shell '${requested}' not found on this platform`)
    return s
  }
  const chain = IS_WINDOWS ? WINDOWS_FALLBACK : UNIX_FALLBACK
  for (const s of chain) {
    if (isShellAvailable(s)) return s
  }
  throw new Error("No supported shell found on this platform")
}

function buildCommand(shell: ShellName, userCommand: string): string[] {
  const { exe, args, encodingCommand } = SHELL_CONFIGS[shell]
  const finalCmd = IS_WINDOWS && encodingCommand
    ? encodingCommand(userCommand)
    : userCommand
  return [exe, ...args, finalCmd]
}

function persistJobs() {
  try {
    ensureDir(BG_DIR)
    const data = Array.from(jobs.values()).map((j) => ({
      id: j.id,
      command: j.command,
      shell: j.shell,
      status: j.status,
      outputFile: j.outputFile,
      startTime: j.startTime,
      endTime: j.endTime,
      exitCode: j.exitCode,
    }))
    writeFileSync(JOBS_FILE, JSON.stringify(data, null, 2))
  } catch (e: any) {
    console.warn("bg plugin: failed to persist jobs:", e.message)
  }
}

function recoverJobs() {
  ensureDir(BG_DIR)
  if (!existsSync(JOBS_FILE)) return
  try {
    const raw = JSON.parse(readFileSync(JOBS_FILE, "utf-8"))
    if (!Array.isArray(raw)) return
    for (const item of raw) {
      if (!item.id) continue
      if (item.status === "running") item.status = "killed"
      jobs.set(item.id, { ...item, process: undefined })
    }
    persistJobs()
  } catch (e: any) {
    console.warn("bg plugin: failed to recover jobs:", e.message)
  }
}

function cleanupHistory() {
  const completed = Array.from(jobs.values()).filter(
    (j) => j.status !== "running"
  )
  if (completed.length <= MAX_HISTORY) return
  completed.sort((a, b) => a.startTime - b.startTime)
  const toRemove = completed.slice(0, completed.length - MAX_HISTORY)
  for (const j of toRemove) {
    jobs.delete(j.id)
    try { unlinkSync(j.outputFile) } catch {}
  }
  persistJobs()
}

function countRunning(): number {
  let n = 0
  for (const j of jobs.values()) {
    if (j.status === "running") n++
  }
  return n
}

function truncateLog(path: string, currentSize: number) {
  if (currentSize <= MAX_LOG_SIZE) return
  try {
    const s = statSync(path)
    const fd = openSync(path, "r")
    const buf = Buffer.alloc(MAX_LOG_SIZE)
    const bytesRead = readSync(fd, buf, 0, MAX_LOG_SIZE, s.size - MAX_LOG_SIZE)
    closeSync(fd)
    writeFileSync(path, buf.subarray(0, bytesRead))
  } catch {}
}

function readTailLines(path: string, maxLines: number): string {
  try {
    const s = statSync(path)
    const CHUNK = 4096
    const fd = openSync(path, "r")
    const lines: string[] = []
    let remaining = s.size
    let leftover = ""

    while (remaining > 0 && lines.length < maxLines) {
      const chunkSize = Math.min(CHUNK, remaining)
      remaining -= chunkSize
      const buf = Buffer.alloc(chunkSize)
      readSync(fd, buf, 0, chunkSize, remaining)
      const chunk = buf.toString("utf-8") + leftover
      const chunkLines = chunk.split("\n")
      leftover = chunkLines.shift() || ""
      lines.unshift(...chunkLines)
    }

    if (leftover) lines.unshift(leftover)
    closeSync(fd)
    if (lines.length > maxLines) return lines.slice(-maxLines).join("\n")
    return lines.join("\n")
  } catch {
    return ""
  }
}

export default (async (ctx) => {
  ensureDir(BG_DIR)
  recoverJobs()

  // TODO: tools and lifecycle
  return {
    tool: {
      bg_start: tool({
        description:
          "Start a shell command in the background without blocking the session. Returns a job ID for tracking progress and output.",
        args: {
          command: tool.schema.string().describe("The shell command to execute"),
          shell: tool.schema
            .string()
            .optional()
            .describe(
              "Shell to use - pwsh, powershell, cmd, bash, sh, zsh. Auto-detected if not specified."
            ),
          cwd: tool.schema
            .string()
            .optional()
            .describe("Working directory, defaults to project root"),
          timeout: tool.schema
            .number()
            .optional()
            .describe("Timeout in seconds after which the job is killed"),
        },
        async execute(args, context) {
          if (!args.command?.trim()) return "Error: Command cannot be empty"

          if (countRunning() >= MAX_CONCURRENT)
            return "Error: Too many background jobs (max 20). Stop some jobs first."

          let shell: ShellName
          try {
            shell = resolveShell(args.shell)
          } catch (e: any) {
            return `Error: ${e.message}`
          }

          const id = genJobId()
          const outputFile = join(BG_DIR, `${id}.log`)
          const cmdArgs = buildCommand(shell, args.command.trim())

          let proc: any
          try {
            proc = Bun.spawn(cmdArgs, {
              cwd: args.cwd || context.directory,
              stdout: "pipe",
              stderr: "pipe",
            })
          } catch (e: any) {
            return `Error: Failed to start process: ${e.message}`
          }

          const job: JobInfo = {
            id,
            command: args.command,
            shell,
            status: "running",
            process: proc,
            outputFile,
            startTime: Date.now(),
          }

          let timeoutId: any = null
          if (args.timeout && args.timeout > 0) {
            timeoutId = setTimeout(() => {
              if (job.status === "running") {
                proc.kill()
                job.status = "timeout"
                job.endTime = Date.now()
                persistJobs()
              }
            }, args.timeout * 1000)
          }

          let logSize = 0
          const writeToLog = (data: Buffer) => {
            try {
              appendFileSync(outputFile, data)
              logSize += data.length
              if (logSize > MAX_LOG_SIZE + 1024 * 1024) {
                truncateLog(outputFile, logSize)
              }
            } catch {}
          }

          ;(async () => {
            try {
              const reader = proc.stdout.getReader()
              while (true) {
                const { done, value } = await reader.read()
                if (done) break
                writeToLog(Buffer.from(value))
              }
            } catch {}
          })()

          ;(async () => {
            try {
              const reader = proc.stderr.getReader()
              while (true) {
                const { done, value } = await reader.read()
                if (done) break
                writeToLog(Buffer.from(value))
              }
            } catch {}
          })()

          proc.exited.then((exitCode: number) => {
            if (timeoutId) clearTimeout(timeoutId)
            if (job.status === "killed" || job.status === "timeout") return
            job.process = undefined
            job.exitCode = exitCode
            job.status = exitCode === 0 ? "completed" : "failed"
            job.endTime = Date.now()
            persistJobs()
            cleanupHistory()
          })

          jobs.set(id, job)
          persistJobs()

          return JSON.stringify({
            job_id: id,
            status: "running",
            shell,
            outputFile,
          })
        },
      }),
      bg_list: tool({
        description:
          "List all background jobs with their status. Shows both running and completed jobs. Use to check which jobs are running or to find job IDs for status/output queries.",
        args: {},
        async execute() {
          const list = Array.from(jobs.values()).map((j) => ({
            id: j.id,
            command: j.command,
            shell: j.shell,
            status: j.status,
            startTime: j.startTime,
            endTime: j.endTime ?? null,
            exitCode: j.exitCode ?? null,
          }))
          return JSON.stringify(list)
        },
      }),
      bg_output: tool({
        description:
          "Get the most recent output from a background job's log file. Use to check progress or view results of running or completed jobs.",
        args: {
          id: tool.schema.string().describe("The job ID"),
          lines: tool.schema
            .number()
            .optional()
            .default(50)
            .describe("Number of recent lines to return (max 500)"),
        },
        async execute(args) {
          const job = jobs.get(args.id)
          if (!job) return `Error: Job '${args.id}' not found`

          if (!existsSync(job.outputFile))
            return `Error: Output file not available for job '${args.id}'`

          const n = Math.min(Math.max(args.lines ?? 50, 1), 500)
          const output = readTailLines(job.outputFile, n)

          return JSON.stringify({
            job_id: job.id,
            status: job.status,
            output,
            truncated: output.split("\n").length >= n,
          })
        },
      }),
      bg_stop: tool({
        description:
          "Stop a running background job by its ID. On Unix sends SIGTERM first then SIGKILL after 5s. On Windows calls process.kill().",
        args: {
          id: tool.schema.string().describe("The job ID to stop"),
        },
        async execute(args) {
          const job = jobs.get(args.id)
          if (!job) return `Error: Job '${args.id}' not found`

          if (job.status !== "running")
            return `Error: Job '${args.id}' already finished (status: ${job.status})`

          job.status = "killed"

          if (!IS_WINDOWS && job.process) {
            try { job.process.kill("SIGTERM") } catch {}
            setTimeout(() => {
              try { job.process?.kill("SIGKILL") } catch {}
            }, 5000)
          } else if (job.process) {
            try { job.process.kill() } catch {}
          }

          job.endTime = Date.now()
          persistJobs()

          return JSON.stringify({ job_id: args.id, status: "killed" })
        },
      }),
    },
    dispose: async () => {
        for (const job of jobs.values()) {
          if (job.status === "running" && job.process) {
            try { job.process.kill() } catch {}
            job.status = "killed"
            job.endTime = Date.now()
            job.process = undefined
          }
        }
        persistJobs()
      },
  }
}) satisfies Plugin
